+            runner,
+            slow_runner,
+            metrics_cache: Mutex::new(None),
+            metrics_refresh: Mutex::new(()),
+            mappings_cache: Mutex::new(None),
+            map_lock: Mutex::new(()),
+            snapshot_lock: Mutex::new(()),
