+            Some(2) => return CubecowError::NotFound(what.to_string()),
+            Some(17) => return CubecowError::AlreadyExists(what.to_string()),
+            // EBUSY(16) / ENOTEMPTY(39): the object is positively
+            // blocked (mapped, watched, or has dependents) — a
