+            || reason.contains("image still has watchers")
+            || reason.contains("(39) Directory not empty")
+            || reason.contains("image has snapshots")
+        {
+            return CubecowError::PreconditionFailed(format!("{what}: {cmd}: {reason}"));
+        }
