+impl ImageKind {
+    fn prefix(self) -> &'static str {
+        match self {
+            ImageKind::Volume => VOLUME_PREFIX,
+            ImageKind::Snapshot => SNAPSHOT_PREFIX,
+        }
+    }
+
+    /// Pool image name for an engine name of this kind.
+    fn image_name(self, name: &str) -> String {
+        format!("{}{}", self.prefix(), name)
+    }
