+    fn snapshot_view(name: &str, origin: &str, info: &RbdInfo, device_path: String) -> Snapshot {
+        Snapshot {
+            name: name.to_string(),
+            size_bytes: info.size,
+            device_path,
+            origin_volume: origin.to_string(),
