+    fn delete_volume(&self, name: &str) -> CubecowResult<()> {
+        if self.resolve(name)?.kind != ImageKind::Volume {
+            return Err(CubecowError::InvalidArg(format!(
+                "'{name}' is a snapshot; use delete_snapshot instead"
+            )));
+        }
