+		cfg.JWTSecret = v
+	}
+	if v := os.Getenv("DATABASE_URL"); v != "" {
+		cfg.DatabaseURL = v
+	}
+	if v := os.Getenv("CUBE_SANDBOX_MYSQL_HOST"); v != "" {
