+// sandboxStateFromRaw handles status that may be string or int.
+func sandboxStateFromRaw(raw json.RawMessage) string {
+	// Try string first.
+	var s string
+	if json.Unmarshal(raw, &s) == nil {
+		switch strings.ToLower(s) {
+		case "paused", "pause":
+			return "paused"
+		case "pausing":
+			return "pausing"
+		case "1":
+			return "running"
+		case "2":
+			return "running"
+		case "4":
+			return "pausing"
+		case "5":
+			return "paused"
+		default:
+			return "running"
+		}
+	}
+	// Try int.
+	var n int
+	if json.Unmarshal(raw, &n) == nil {
