+		return s
+	}
+	var n int64
+	if json.Unmarshal(raw, &n) == nil {
+		if n > 1_000_000_000_000 {
+			// Milliseconds.
+			return time.Unix(n/1000, 0).UTC().Format(time.RFC3339)
+		}
+		if n > 0 {
+			// Seconds.
+			return time.Unix(n, 0).UTC().Format(time.RFC3339)
+		}
+	}
+	return ""
+}
