+	// Wrap in Connect envelope: [0x00] [4-byte big-endian length] [payload]
+	body := make([]byte, 5+len(payload))
+	body[0] = 0
+	binary.BigEndian.PutUint32(body[1:5], uint32(len(payload)))
+	copy(body[5:], payload)
