+func writeTerminalFrame(conn *websocket.Conn, frame terminalServerFrame) error {
+	if err := conn.SetWriteDeadline(time.Now().Add(terminalWriteTimeout)); err != nil {
+		return err
+	}
+	return conn.WriteJSON(frame)
+}
