+    let mut payload = json!({
+        "process": {
+            "cmd": "/bin/bash",
+            "args": ["-i", "-l"],
+            "envs": {
+                "TERM": "xterm-256color",
+                "LANG": "C.UTF-8",
+                "LC_ALL": "C.UTF-8"
+            }
+        },
+        "pty": {
+            "size": {
+                "rows": size.rows,
+                "cols": size.cols
+            }
+        }
+    });
+
+    if let Some(container_id) = selected_container_id {
+        payload["process"]["container_id"] = json!(container_id);
+    }
+
+    payload
